// Standalone host test for the native MTP2 encoder.
// Build with CMake/CTest or compile with -I native and native/pmini_codec.cpp.
// Assertions include encoder calls and must execute in Release builds too.
#ifdef NDEBUG
#undef NDEBUG
#endif

#include "pmini_codec.h"

#include <cassert>
#include <cstdint>
#include <iostream>
#include <string>
#include <vector>

static std::string hex(const std::string& in) {
    static constexpr char digits[] = "0123456789abcdef";
    std::string out;
    out.reserve(in.size() * 2);
    for (unsigned char c : in) {
        out.push_back(digits[c >> 4]);
        out.push_back(digits[c & 15]);
    }
    return out;
}

int main() {
    constexpr std::size_t rows = 32;
    constexpr std::size_t cols = 8;
    std::vector<std::uint32_t> words(rows * cols);
    for (std::size_t r = 0; r < rows; ++r) {
        words[r * cols + 0] = 42;
        words[r * cols + 1] = static_cast<std::uint32_t>(r * 13);
        words[r * cols + 2] = (r % 7 == 0) ? 1000u : 3u;
        words[r * cols + 3] = (r % 4 == 0) ? 0xdeadbeefu : 0x1111u;
        words[r * cols + 4] = (r % 3) ? 8u : 9u;
        words[r * cols + 5] = (r % 5 == 0) ? 0xabcu : 0xdefu;
        words[r * cols + 6] = static_cast<std::uint32_t>(r * 2 + 1);
        words[r * cols + 7] = (r % 4 == 0) ? 0xdeadbeefu : 0x1111u;
    }

    std::string encoded;
    assert(pminiEncode(words.data(), rows, cols, encoded));
    // Golden bytes generated by /Users/fab/dev/esp/pmini/pmini/pmini.py and
    // independently checked with pmini.decode_words(..., ['I'] * 8).
    assert(hex(encoded) ==
           "4d5450322008305401c6abaaaaaaaaaaaaaa15662a1d057d6f131111"
           "aa0b7cf76df5f612885335447a99f7e62a1986575d4133371191087cf7"
           "6df576245d40e10136000500080093e2aae6");

    // Invalid input must not partially append to a caller-owned packet.
    std::string unchanged = "prefix";
    assert(!pminiEncode(nullptr, 1, 1, unchanged));
    assert(unchanged == "prefix");
    assert(!pminiEncode(words.data(), 129, cols, unchanged));
    assert(unchanged == "prefix");

    // Zero-sized dimensions are refused rather than producing an unusable
    // schema-less shard.
    assert(!pminiEncode(nullptr, 0, cols, unchanged));
    assert(!pminiEncode(nullptr, rows, 0, unchanged));
    assert(unchanged == "prefix");

    // Appending after an existing packet must CRC only the new shard, not the
    // caller's prefix.
    const std::string goldenSuffix = encoded;
    std::string prefixed = "prefix";
    assert(pminiEncode(words.data(), rows, cols, prefixed));
    assert(prefixed.substr(6) == goldenSuffix);

    std::cout << "pmini native golden/guard tests passed (" << encoded.size()
              << " bytes)\n";
}
